    un_pts = un_list
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if not inb(nx, ny):
            continue

        pos = (nx, ny)
        score = 0

        if pos in self_set:
            score += 2
        elif pos in un_set:
            score += 6
        elif pos in opp_set:
