        score += 0.6 * (20 - min(d_un, 20))

        # Tie-break deterministically by move ordering and then position.
        if score > best_score or (score == best_score and (dx, dy) < best_move):
            best_score = score
            best_move = (dx, dy)

    return [int(best_move[0]), int(best_move[1])]

